// Deterministic layout maths shared by the renderer and the validator.
// No DOM measurement: widths come from per-glyph advance tables (src/lib/font-metrics.json,
// generated by scripts/font-metrics.mjs) embedded into spec.json by the compiler, so Node-side
// validation and browser-side rendering agree to the pixel.

export const unitFor = (width, height) => Math.min(width, height) / 1080;

/** Rendered width in px of a single-line string at fontSize 1px for a resolved role.
 * Uses the exact per-glyph advance table embedded by the compiler (role.advances, from
 * scripts/font-metrics.mjs); falls back to role.avg_char_width_em for unknown glyphs. */
export function widthAt1px(text, role) {
  const adv = role.advances || {};
  const avg = role.avg_char_width_em ?? 0.6;
  const cs = Array.from(String(text));
  let w = 0;
  for (const ch of cs) w += adv[ch] ?? avg;
  return w + cs.length * (role.tracking_em || 0);
}

export function estimateWidth(text, role, unit) {
  return widthAt1px(text, role) * role.size_px * unit;
}

/**
 * Resolve the font size of one text element.
 *  fit: 'fill'   -> scale so the line spans exactly the column width, clamped to [min_px, size_px]
 *                   (the demo's justified-column look: every display line is the same width)
 *  fit: 'shrink' -> use size_px; scale down only if the line would overflow (floor: min_scale)
 *  fit: 'wrap'   -> use size_px; the line may wrap (body copy)
 * @returns {{fontSize:number, scale:number, ok:boolean, lines:number}}
 */
export function resolveSize(text, role, unit, maxWidthPx, sizeMul = 1) {
  const w1 = widthAt1px(text, role) || 1;
  const base = role.size_px * unit * sizeMul;
  const fit = role.fit || (role.min_scale ? 'shrink' : 'wrap');
  if (fit === 'fill') {
    const ideal = maxWidthPx / w1;
    const min = (role.min_px ?? role.size_px * 0.5) * unit;
    const size = Math.min(base, ideal);
    return { fontSize: Math.max(min, size), scale: size / base, ok: ideal >= min, lines: 1 };
  }
  if (fit === 'shrink') {
    const s = Math.min(1, maxWidthPx / (w1 * base));
    const floor = role.min_scale ?? 0.6;
    return { fontSize: base * Math.max(s, floor), scale: s, ok: s >= floor, lines: 1 };
  }
  const lines = Math.ceil((w1 * base) / maxWidthPx);
  return { fontSize: base, scale: 1, ok: lines <= (role.max_lines ?? 2), lines };
}

/** Back-compat helper used by older templates. */
export function fitScale(text, role, unit, maxWidthPx) {
  return resolveSize(text, role, unit, maxWidthPx).scale;
}

/** Content box (px) inside the safe area for a format. */
export function contentBox(design, width, height) {
  const sa = design.safe_area;
  const left = Math.round(width * sa.left);
  const right = Math.round(width * sa.right);
  const top = Math.round(height * sa.top);
  const bottom = Math.round(height * sa.bottom);
  const maxW = Math.min(width - left - right, Math.round(width * design.layout.text_max_width));
  return { left, right, top, bottom, width: maxW, height: height - top - bottom };
}

/** WCAG relative-luminance contrast ratio between two hex colours. */
export function contrast(hexA, hexB) {
  const lum = (hex) => {
    const h = hex.replace('#', '');
    const c = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255).map((v) => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  };
  const [a, b] = [lum(hexA), lum(hexB)].sort((x, y) => y - x);
  return (a + 0.05) / (b + 0.05);
}
